// Stickerwild — hand-drawn art: Ene in Pink, Star and the moon, cut out of the
// original drawings (art/*.png) and inlined so the game stays a single file.
// Used for close-ups (portraits, the moon, the story); in-game sprites are
// vector redraws in sprites.js.
'use strict';
(function () {
  const SRC = {
    eneFront: 'data:image/png;base64,',
    eneThreeQ: 'data:image/png;base64,',
    eneSide: 'data:image/png;base64,',
    eneBack: 'data:image/png;base64,',
    eneJoy: 'data:image/png;base64,',
    eneCry: 'data:image/png;base64,',
    moonHappy0: 'data:image/png;base64,',
    moonHappy1: 'data:image/png;base64,',
    moonHappy2: 'data:image/png;base64,',
    moonHappy3: 'data:image/png;base64,',
    moonHappy4: 'data:image/png;base64,',
    moonSad0: 'data:image/png;base64,',
    moonSad1: 'data:image/png;base64,',
    moonSad2: 'data:image/png;base64,',
    moonSad3: 'data:image/png;base64,',
    moonSad4: 'data:image/png;base64,',
    starSurprised: 'data:image/png;base64,',
    starHappy: 'data:image/png;base64,',
    starSad: 'data:image/png;base64,',
    starBack: 'data:image/png;base64,',
    starAngry: 'data:image/png;base64,',
    starLaugh: 'data:image/png;base64,',
  };
  SW.ART_IMG = {};
  for (const k in SRC) { const im = new Image(); im.src = SRC[k]; SW.ART_IMG[k] = im; }
  SW.artURL = (k) => SRC[k] || '';
  SW.artReady = (k) => { const im = SW.ART_IMG[k]; return !!(im && im.complete && im.naturalWidth); };
})();
